-- Generated by generate_hub_relocation.py; apply with worldserver stopped.
-- Sources: world_hub_points.csv, world_hub_native_spawns.csv, world_areas.csv, world_hub_services.csv.
-- Removes only surveyed native placements, never terrain/WMO scenery or templates.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS dc_world_hub_point (name VARCHAR(32) PRIMARY KEY,map_id INT UNSIGNED NOT NULL,area_id INT UNSIGNED NOT NULL,x DOUBLE NOT NULL,y DOUBLE NOT NULL,z DOUBLE NOT NULL,o DOUBLE NOT NULL);
CREATE TEMPORARY TABLE dc_hub_native (kind CHAR(1),guid INT UNSIGNED,entry INT UNSIGNED,PRIMARY KEY(kind,guid));
CREATE TEMPORARY TABLE dc_hub_remove_c AS SELECT s.guid FROM creature s JOIN dc_hub_native n ON n.kind='c' AND n.guid=s.guid AND n.entry=s.id WHERE s.map=530;
DELETE s FROM `creature_addon` s JOIN dc_hub_remove_c v ON v.guid=s.`guid`;
DELETE s FROM `creature_movement_override` s JOIN dc_hub_remove_c v ON v.guid=s.`SpawnId`;
DELETE s FROM `creature_multispawn` s JOIN dc_hub_remove_c v ON v.guid=s.`spawnId`;
DELETE s FROM `creature_sparring` s JOIN dc_hub_remove_c v ON v.guid=s.`GUID`;
DELETE s FROM `vehicle_accessory` s JOIN dc_hub_remove_c v ON v.guid=s.`guid`;
DELETE s FROM `pool_creature` s JOIN dc_hub_remove_c v ON v.guid=s.`guid`;
DELETE s FROM `game_event_creature` s JOIN dc_hub_remove_c v ON v.guid=s.`guid`;
DELETE s FROM `game_event_model_equip` s JOIN dc_hub_remove_c v ON v.guid=s.`guid`;
DELETE s FROM `game_event_npc_vendor` s JOIN dc_hub_remove_c v ON v.guid=s.`guid`;
DELETE s FROM `game_event_npcflag` s JOIN dc_hub_remove_c v ON v.guid=s.`guid`;
DELETE s FROM spawn_group s JOIN dc_hub_remove_c v ON v.guid=s.spawnId WHERE s.spawnType=0;
DELETE s FROM smart_scripts s JOIN dc_hub_remove_c v ON s.entryorguid=-CAST(v.guid AS SIGNED) WHERE s.source_type=0;
DELETE s FROM conditions s JOIN dc_hub_remove_c v ON s.SourceEntry=-CAST(v.guid AS SIGNED) WHERE s.SourceTypeOrReferenceId=22 AND s.SourceId=0;
DELETE s FROM conditions s JOIN dc_hub_remove_c v ON s.ConditionValue3=v.guid WHERE s.ConditionTypeOrReference=31 AND s.ConditionValue1=3;
CREATE TEMPORARY TABLE dc_hub_remove_g AS SELECT s.guid FROM gameobject s JOIN dc_hub_native n ON n.kind='g' AND n.guid=s.guid AND n.entry=s.id WHERE s.map=530;
DELETE s FROM `gameobject_addon` s JOIN dc_hub_remove_g v ON v.guid=s.`guid`;
DELETE s FROM `pool_gameobject` s JOIN dc_hub_remove_g v ON v.guid=s.`guid`;
DELETE s FROM `game_event_gameobject` s JOIN dc_hub_remove_g v ON v.guid=s.`guid`;
DELETE s FROM spawn_group s JOIN dc_hub_remove_g v ON v.guid=s.spawnId WHERE s.spawnType=1;
DELETE s FROM smart_scripts s JOIN dc_hub_remove_g v ON s.entryorguid=-CAST(v.guid AS SIGNED) WHERE s.source_type=1;
DELETE s FROM conditions s JOIN dc_hub_remove_g v ON s.SourceEntry=-CAST(v.guid AS SIGNED) WHERE s.SourceTypeOrReferenceId=22 AND s.SourceId=1;
DELETE s FROM conditions s JOIN dc_hub_remove_g v ON s.ConditionValue3=v.guid WHERE s.ConditionTypeOrReference=31 AND s.ConditionValue1=5;
DELETE s FROM creature_formations s JOIN dc_hub_remove_c v ON v.guid=s.leaderGUID;
DELETE s FROM creature_formations s JOIN dc_hub_remove_c v ON v.guid=s.memberGUID;
DELETE s FROM linked_respawn s JOIN dc_hub_remove_c v ON v.guid=s.guid WHERE s.linkType IN (0,1);
DELETE s FROM linked_respawn s JOIN dc_hub_remove_c v ON v.guid=s.linkedGuid WHERE s.linkType IN (0,3);
DELETE s FROM linked_respawn s JOIN dc_hub_remove_g v ON v.guid=s.guid WHERE s.linkType IN (2,3);
DELETE s FROM linked_respawn s JOIN dc_hub_remove_g v ON v.guid=s.linkedGuid WHERE s.linkType IN (1,2);
DELETE s FROM dc_area_source s JOIN dc_hub_remove_c v ON v.guid=s.source_guid WHERE s.kind='c';
DELETE s FROM dc_area_spawn s JOIN dc_hub_remove_c v ON v.guid=s.spawn_guid WHERE s.kind='c';
DELETE s FROM creature s JOIN dc_hub_remove_c v ON v.guid=s.guid;
DELETE s FROM dc_area_source s JOIN dc_hub_remove_g v ON v.guid=s.source_guid WHERE s.kind='g';
DELETE s FROM dc_area_spawn s JOIN dc_hub_remove_g v ON v.guid=s.spawn_guid WHERE s.kind='g';
DELETE s FROM gameobject s JOIN dc_hub_remove_g v ON v.guid=s.guid;
-- Generated from data/d3/world_areas.csv; edit the CSV and rerun generate_sql.py.
-- Apply to the world database.
SET NAMES utf8mb4;
DROP TABLE IF EXISTS `dc_world_areas`;
CREATE TABLE `dc_world_areas` (
  `map_id` BIGINT NULL,
  `area_id` BIGINT NULL,
  `phase_scope` LONGTEXT NOT NULL,
  `status` LONGTEXT NOT NULL,
  `note` LONGTEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

UPDATE playercreateinfo c JOIN dc_world_hub_point p ON p.name='spawn' SET c.map=p.map_id,c.zone=p.area_id,c.position_x=p.x,c.position_y=p.y,c.position_z=p.z,c.orientation=p.o WHERE c.class=1;
DELETE FROM creature_template WHERE entry=910003;
DELETE FROM creature_template_model WHERE CreatureID=910003;
DROP TEMPORARY TABLE dc_hub_remove_c,dc_hub_remove_g,dc_hub_native;
